function ControllerMobileButtonsManager:OnDestroy()

    currentInstance = nil

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- 在 餐厅/春节 等场景, 并没有猫交互按钮, 此时允许 本函数等不到
function ControllerMobileButtonsManager.WaitInstance()
    -- 只等待有限帧
    for i=1,DreamSpaceStates.DelayInitWaitFrames do 
        if isNotNull(currentInstance) then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end 
    print( "koko - 始终没等到 ControllerMobileButtonsManager 实例化, 但这是允许的" )
end


